import { useEffect } from "react";
import { jsx } from "react/jsx-runtime";

export const Button = ({ onClick, onPointerDownCapture, children }) =>
  jsx("button", { type: "button", onClick, onPointerDownCapture, children });

export const Field = ({ value, onChange }) => {
  useEffect(() => {
    onChange(value.trim());
  }, [onChange, value]);
  return jsx("input", { value, readOnly: true });
};
